package dev.kof.compiler;

import java.util.Base64;

/**
 * Independent data source for AVIF slice 3c (the AV1 default coefficient
 * CDFs, {@code libs/image/Av1CoeffCdf.kf}). The Kof module embeds the values
 * exactly as published in the AV1 spec §10 (additional tables); this class
 * embeds the same 13 tables independently derived from libaom's
 * {@code av1/common/token_cdfs.h} (the {@code AOM_CDFn} macros expanded to the
 * spec CDF shape, the unused duplicate of the 512/1024 tables dropped),
 * decoded from a big-endian uint16 base64 blob. {@link #golden()} walks every
 * CDF exactly as the Kof probe does; the test requires the two to be equal
 * value-for-value across all ~16k numbers.
 */
final class Av1CoeffCdfSupport {

    private Av1CoeffCdfSupport() {}

    private static final String TXB_SKIP_B64 =
        "";

    private static final String EOB_PT_16_B64 =
        "A0gEDwe8Ex+AAAAAAXICnwdbEXeAAAAADK8TViXYOOOAAAAAB3ANGh5TOTeAAAAACE0J9xQtIvKAAAAAAgEC/QdDGMOAAAAAHdUlGjezSqSAAAAACcEQACKiQmGAAAAAD7ATISKxOniAAAAAAswEUQpWJ0iAAAAAK4Mz1kdBXA6AAAAADHgTqCg5TSuAAAAAGjQi/jmaVnWAAAAABMYIGhKvPDKAAAAATHdVBmW8dA2AAAAAHIEqD0tJbiKAAAAA";

    private static final String EOB_PT_32_B64 =
        "";

    private static final String EOB_PT_64_B64 =
        "";

    private static final String EOB_PT_128_B64 =
        "";

    private static final String EOB_PT_256_B64 =
        "";

    private static final String EOB_PT_512_B64 =
        "AoED1w57FTYn+jpuSWRbdGXNgAAAABPnGS4nDDQqPpFGQlG3ZhFx1IAAAAAEzgjmE6seYC5fO/JMhmAIcE2AAAAAHGEm+z3LSzJVFF0mZ25u7HxDgAAAAApAD2AZUCXWNptFPlrjbvp5ZoAAAAAu7zmxTIRWJF6eZNRqpHIjfXKAAAAAFycegSqrOQVL715Hbyh5pn08gAAAAFJlWgNkjmwKcal0FHV5eGR81IAAAAA=";

    private static final String EOB_PT_1024_B64 =
        "AYkBpQLvBlcMWBjQNCFGf1grZOaAAAAAB0kHxAtyEJIpJUCaU2pqd2+CfCiAAAAAArgDtAxJFkYl6jOhRbtVYGRcbYKAAAAACnAOByRyQrxYxV7cZ59te27ZeJyAAAAACuAO9xuBKRk5/0mcWnNoOnIteUWAAAAAJWkwskVLUQ5WLVqvYBlji2TzfTiAAAAAGiogji65PZJO2l02aypyjnlqfTKAAAAAUFlXmmPhaOttlXDxcy50HHRvfzqAAAAA";

    private static final String EOB_EXTRA_B64 =
        "";

    private static final String DC_SIGN_B64 =
        "PoCAAAAAMwCAAAAASYCAAAAAO4CAAAAAMoCAAAAAQ4CAAAAAPoCAAAAAMwCAAAAASYCAAAAAO4CAAAAAMoCAAAAAQ4CAAAAAPoCAAAAAMwCAAAAASYCAAAAAO4CAAAAAMoCAAAAAQ4CAAAAAPoCAAAAAMwCAAAAASYCAAAAAO4CAAAAAMoCAAAAAQ4CAAAAA";

    private static final String COEFF_BASE_EOB_B64 =
        "";

    private static final String COEFF_BASE_B64 =
        "";

    private static final String COEFF_BR_B64 =
        "";

    static final int[] TXB_SKIP = decode(TXB_SKIP_B64);
    static final int[] EOB_PT_16 = decode(EOB_PT_16_B64);
    static final int[] EOB_PT_32 = decode(EOB_PT_32_B64);
    static final int[] EOB_PT_64 = decode(EOB_PT_64_B64);
    static final int[] EOB_PT_128 = decode(EOB_PT_128_B64);
    static final int[] EOB_PT_256 = decode(EOB_PT_256_B64);
    static final int[] EOB_PT_512 = decode(EOB_PT_512_B64);
    static final int[] EOB_PT_1024 = decode(EOB_PT_1024_B64);
    static final int[] EOB_EXTRA = decode(EOB_EXTRA_B64);
    static final int[] DC_SIGN = decode(DC_SIGN_B64);
    static final int[] COEFF_BASE_EOB = decode(COEFF_BASE_EOB_B64);
    static final int[] COEFF_BASE = decode(COEFF_BASE_B64);
    static final int[] COEFF_BR = decode(COEFF_BR_B64);

    private static int[] decode(String b64) {
        byte[] raw = Base64.getDecoder().decode(b64);
        int[] out = new int[raw.length / 2];
        for (int i = 0; i < out.length; i++) {
            out[i] = ((raw[i * 2] & 0xFF) << 8) | (raw[i * 2 + 1] & 0xFF);
        }
        return out;
    }

    static int[] slice(int[] flat, int index, int n) {
        int[] out = new int[n];
        System.arraycopy(flat, index * n, out, 0, n);
        return out;
    }

    private static void row(StringBuilder sb, int[] a) {
        for (int i = 0; i < a.length; i++) {
            if (i > 0) sb.append(' ');
            sb.append(a[i]);
        }
        sb.append('\n');
    }

    /** The canonical dump the Kof probe must reproduce. */
    static String golden() {
        StringBuilder sb = new StringBuilder();
        for (int q = 0; q < 4; q++) {
            for (int tx = 0; tx < 5; tx++)
                for (int ctx = 0; ctx < 13; ctx++)
                    row(sb, slice(TXB_SKIP, (q * 5 + tx) * 13 + ctx, 3));
            for (int n : new int[]{16, 32, 64, 128, 256, 512, 1024}) {
                int[] tab = eobTable(n);
                int per = eobLen(n);
                int nctx = n <= 256 ? 2 : 1;
                for (int p = 0; p < 2; p++)
                    for (int c = 0; c < nctx; c++)
                        row(sb, slice(tab, (q * 2 + p) * nctx + c, per));
            }
            for (int tx = 0; tx < 5; tx++)
                for (int p = 0; p < 2; p++)
                    for (int c = 0; c < 9; c++)
                        row(sb, slice(EOB_EXTRA, ((q * 5 + tx) * 2 + p) * 9 + c, 3));
            for (int p = 0; p < 2; p++)
                for (int c = 0; c < 3; c++)
                    row(sb, slice(DC_SIGN, (q * 2 + p) * 3 + c, 3));
            for (int tx = 0; tx < 5; tx++)
                for (int p = 0; p < 2; p++)
                    for (int c = 0; c < 4; c++)
                        row(sb, slice(COEFF_BASE_EOB, ((q * 5 + tx) * 2 + p) * 4 + c, 4));
            for (int tx = 0; tx < 5; tx++)
                for (int p = 0; p < 2; p++)
                    for (int c = 0; c < 42; c++)
                        row(sb, slice(COEFF_BASE, ((q * 5 + tx) * 2 + p) * 42 + c, 5));
            for (int tx = 0; tx < 5; tx++)
                for (int p = 0; p < 2; p++)
                    for (int c = 0; c < 21; c++)
                        row(sb, slice(COEFF_BR, ((q * 5 + Math.min(tx, 3)) * 2 + p) * 21 + c, 5));
        }
        return sb.toString().strip();
    }

    static int[] eobTable(int n) {
        return switch (n) {
            case 16 -> EOB_PT_16;
            case 32 -> EOB_PT_32;
            case 64 -> EOB_PT_64;
            case 128 -> EOB_PT_128;
            case 256 -> EOB_PT_256;
            case 512 -> EOB_PT_512;
            default -> EOB_PT_1024;
        };
    }

    static int eobLen(int n) {
        return switch (n) {
            case 16 -> 6;
            case 32 -> 7;
            case 64 -> 8;
            case 128 -> 9;
            case 256 -> 10;
            case 512 -> 11;
            default -> 12;
        };
    }

    /** Kof probe source that dumps every CDF through the Kof accessors. */
    static String kofProbe() {
        return PROBE;
    }

    private static final String PROBE = """
import image.Av1CoeffCdf

void av1CdfRow(Int[] a) {
    var s = ""
    var i = 0
    while (i < a.size) {
        if (i > 0) {
            s = s + " "
        }
        s = s + a[i]
        i = i + 1
    }
    println(s)
}

main() {
    var q = 0
    while (q < 4) {
        var c = Av1CoeffCdf(q)
        var tx = 0
        while (tx < 5) {
            var ctx = 0
            while (ctx < 13) {
                av1CdfRow(c.txbSkipCdf(tx, ctx))
                ctx = ctx + 1
            }
            tx = tx + 1
        }
        var p16 = 0
        while (p16 < 2) {
            var c16 = 0
            while (c16 < 2) {
                av1CdfRow(c.eobPtCdf(16, p16, c16))
                c16 = c16 + 1
            }
            p16 = p16 + 1
        }
        var p32 = 0
        while (p32 < 2) {
            var c32 = 0
            while (c32 < 2) {
                av1CdfRow(c.eobPtCdf(32, p32, c32))
                c32 = c32 + 1
            }
            p32 = p32 + 1
        }
        var p64 = 0
        while (p64 < 2) {
            var c64 = 0
            while (c64 < 2) {
                av1CdfRow(c.eobPtCdf(64, p64, c64))
                c64 = c64 + 1
            }
            p64 = p64 + 1
        }
        var p128 = 0
        while (p128 < 2) {
            var c128 = 0
            while (c128 < 2) {
                av1CdfRow(c.eobPtCdf(128, p128, c128))
                c128 = c128 + 1
            }
            p128 = p128 + 1
        }
        var p256 = 0
        while (p256 < 2) {
            var c256 = 0
            while (c256 < 2) {
                av1CdfRow(c.eobPtCdf(256, p256, c256))
                c256 = c256 + 1
            }
            p256 = p256 + 1
        }
        var p512 = 0
        while (p512 < 2) {
            var c512 = 0
            while (c512 < 1) {
                av1CdfRow(c.eobPtCdf(512, p512, c512))
                c512 = c512 + 1
            }
            p512 = p512 + 1
        }
        var p1024 = 0
        while (p1024 < 2) {
            var c1024 = 0
            while (c1024 < 1) {
                av1CdfRow(c.eobPtCdf(1024, p1024, c1024))
                c1024 = c1024 + 1
            }
            p1024 = p1024 + 1
        }
        var e = 0
        while (e < 5) {
            var ep = 0
            while (ep < 2) {
                var ec = 0
                while (ec < 9) {
                    av1CdfRow(c.eobExtraCdf(e, ep, ec))
                    ec = ec + 1
                }
                ep = ep + 1
            }
            e = e + 1
        }
        var d = 0
        while (d < 2) {
            var dc = 0
            while (dc < 3) {
                av1CdfRow(c.dcSignCdf(d, dc))
                dc = dc + 1
            }
            d = d + 1
        }
        var b = 0
        while (b < 5) {
            var bp = 0
            while (bp < 2) {
                var bc = 0
                while (bc < 4) {
                    av1CdfRow(c.coeffBaseEobCdf(b, bp, bc))
                    bc = bc + 1
                }
                bp = bp + 1
            }
            b = b + 1
        }
        var t = 0
        while (t < 5) {
            var tp = 0
            while (tp < 2) {
                var tc = 0
                while (tc < 42) {
                    av1CdfRow(c.coeffBaseCdf(t, tp, tc))
                    tc = tc + 1
                }
                tp = tp + 1
            }
            t = t + 1
        }
        var r = 0
        while (r < 5) {
            var rp = 0
            while (rp < 2) {
                var rc = 0
                while (rc < 21) {
                    av1CdfRow(c.coeffBrCdf(r, rp, rc))
                    rc = rc + 1
                }
                rp = rp + 1
            }
            r = r + 1
        }
        q = q + 1
    }
}
""";
}